// 过滤出评论里含 #vk-<任务ID> 或 #recur-<标识> 且本工作流尚未处理过的交易
const sd = $workflow.staticData;
if (!sd.lastIds) sd.lastIds = [];
const items = $input.item.json.result || $input.item.json || {};
const txs = Array.isArray(items) ? items : (items.transactions || []);
const out = [];
for (const tx of txs) {
  const comment = (tx.comment || '').toString();
  if (!sd.lastIds.includes(tx.id)) {
    const mv = comment.match(/#vk-(\d+)/);
    const mr = comment.match(/#recur-([\w-]+)/);
    if (mv) {
      out.push({ json: { kind: 'vk', txId: tx.id, taskId: parseInt(mv[1], 10), comment: comment, amount: tx.sourceAmount, type: tx.type } });
    } else if (mr) {
      out.push({ json: { kind: 'recur', txId: tx.id, token: '#recur-' + mr[1], comment: comment, amount: tx.sourceAmount, type: tx.type } });
    }
    sd.lastIds.push(tx.id);
  }
}
// 仅保留最近 200 条去重记录
sd.lastIds = sd.lastIds.slice(-200);
return out;

