// 拉到带 #recur-<标识> 的 ezB 周期过账后，自动把对应 Vikunja 那个月份、未完成的 recur 任务标记为已完成
// 闭环：ezB 周期交易（权威扣款） → 此节点 → Vikunja recur 任务 done=true + 回写评论
// 依赖 B6：Vikunja recurring 完成任务生成新实例时，需继承原任务的 `recur` 与 `#recur-<标识>` 标签，否则按标签找不到新实例、闭环断裂。
return await (async () => {
const token = $json.token;
const txId = $json.txId;
const comment = $json.comment || '';
const auth = 'Bearer ' + $vars.vikunja_token;
const base = 'http://vikunja:3456/api/v1';
try {
  const listResp = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/tasks?per_page=200',
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true
  });
  const tasks = Array.isArray(listResp) ? listResp : (listResp.tasks || []);
  const matches = tasks.filter(t => {
    const labels = (t.labels || []).map(l => (l && l.title !== undefined ? l.title : l).toString());
    return !t.done && labels.includes('recur') && labels.includes(token);
  });
  if (matches.length !== 1) {
    return [{ json: { token, txId, found: false, count: matches.length, note: '未找到唯一未完成的 recur 任务（0 或多个），跳过，避免误勾' } }];
  }
  const taskId = matches[0].id;
  // 标记完成（v2.5.0 无 /tasks/{id}/done 端点，用 POST /tasks/{id} 置 done=true）
  await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/tasks/' + taskId,
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true,
    body: { done: true }
  });
  // 回写评论
  await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/tasks/' + taskId + '/comments',
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true,
    body: { comment: 'by:ezB周期交易 已扣款，任务自动勾选完成（交易ID ' + txId + '）' }
  });
  return [{ json: { token, txId, found: true, taskId } }];
} catch (e) {
  return [{ json: { token, txId, found: false, error: (e && e.message) ? e.message : String(e) } }];
}
})();
